    sell_book = []  # List of (price, arrival_time, order_id, remaining_qty)

    # Track all orders for cancellation purposes
    order_map = {}  # order_id -> (book_type, index_in_book, original_qty)
    arrival_counter = 0

    for order in orders:
        arrival_counter += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                # Remove from the appropriate book
                book_type, book, book_idx = order_map[order_id]
                if book_idx < len(book) and book[book_idx][2] == order_id:
                    book.pop(book_idx)
                    # Update indices for all affected orders
                    for oid in order_map:
                        btype, b, bidx = order_map[oid]
                        if btype == book_type and b is book and bidx > book_idx:
